#include <WiFi.h>
#include <HX711.h>

// --- НАСТРОЙКИ СЕТИ ---
const char* ssid = "CocktailMixer";
const char* password = "12345678";
WiFiServer server(9000);
WiFiClient client;

// --- НАСТРОЙКИ НАСОСОВ ---
// Насосы 1-5 (выходы ESP32)
const int pumpPins[5] = {25, 26, 27, 14, 13}; 
float pumpRates[5] = {5.0, 5.0, 5.0, 5.0, 5.0}; // мл/сек
float pumpInertia[5] = {2.0, 2.0, 2.0, 2.0, 2.0}; // мл (для времени)

// --- НАСТРОЙКИ ДАТЧИКОВ И ВЕСОВ ---
// ИК-датчики (1, 2, 4, 5 места). 3-е место - на весах!
const int irPins[5] = {32, 33, -1, 35, 36}; 

// Настройки весов HX711 (для 3-го места)
const int HX711_DOUT = 4;
const int HX711_SCK = 5;
HX711 scale;
float scaleCalibrationFactor = -471.497; // ВАШ коэффициент калибровки!
float emptyGlassWeight = 0.0; // Вес пустой рюмки (тара)

volatile bool stopRequested = false;

void setup() {
  Serial.begin(115200);
  delay(500);

  // Настройка насосов
  for (int i = 0; i < 5; i++) {
    pinMode(pumpPins[i], OUTPUT);
    digitalWrite(pumpPins[i], LOW);
  }

  // Настройка ИК-датчиков (кроме 3-го)
  for (int i = 0; i < 5; i++) {
    if (irPins[i] != -1) {
      pinMode(irPins[i], INPUT_PULLUP);
    }
  }

  // Инициализация весов HX711
  scale.begin(HX711_DOUT, HX711_SCK);
  scale.set_scale(scaleCalibrationFactor);
  scale.tare(); // Сбрасываем в ноль при старте

  // Запуск Wi-Fi
  WiFi.softAP(ssid, password);
  Serial.print("AP IP: ");
  Serial.println(WiFi.softAPIP());

  server.begin();
  Serial.println("TCP server started on port 9000");
}

void loop() {
  if (!client || !client.connected()) {
    client = server.available();
    if (client) {
      Serial.println("Android app connected");
      client.println("READY");
    }
  }

  if (client && client.connected() && client.available()) {
    String cmd = client.readStringUntil('\n');
    cmd.trim();
    if (cmd.length() > 0) {
      handleCommand(cmd);
    }
  }
}

// ================= ЛОГИКА ОПРЕДЕЛЕНИЯ РЮМОК =================

bool isGlassPresent(int place) {
  if (place < 1 || place > 5) return false;

  // Если это 3-е место (среднее) - проверяем по весам
  if (place == 3) {
    float currentWeight = scale.get_units(5); // берем 5 значений для сглаживания
    // Если вес больше 20 грамм, считаем что рюмка стоит
    return (currentWeight > 20.0); 
  }

  // Для остальных мест - по ИК-датчику (LOW = рюмка есть, т.к. INPUT_PULLUP)
  return digitalRead(irPins[place - 1]) == LOW;
}

void sendGlassStatus(int place) {
  client.print("GLASS:");
  client.print(place);
  client.print(":");
  client.println(isGlassPresent(place) ? "1" : "0");
}

// ================= ОБРАБОТКА КОМАНД =================

void handleCommand(String cmd) {
  Serial.print("Received: "); Serial.println(cmd);

  if (cmd == "PING") { client.println("PONG"); return; }

  if (cmd == "STOP") {
    stopRequested = true;
    for (int i = 0; i < 5; i++) digitalWrite(pumpPins[i], LOW);
    client.println("STOPPED");
    return;
  }

  if (cmd == "CHECK_ALL") {
    for (int i = 1; i <= 5; i++) sendGlassStatus(i);
    client.println("CHECK_DONE");
    return;
  }

  // Калибровка скорости: C1:5.5
  if (cmd.startsWith("C")) {
    int colon = cmd.indexOf(':');
    if (colon > 0) {
      int n = cmd.substring(1, colon).toInt() - 1;
      float rate = cmd.substring(colon + 1).toFloat();
      if (n >= 0 && n < 5 && rate > 0) {
        pumpRates[n] = rate;
        client.print("CAL_OK:"); client.println(n + 1);
      }
    }
    return;
  }

  // НАЛИВ ПО ВРЕМЕНИ (1, 2, 4, 5 места): P1:50:5.2:2.0
  if (cmd.startsWith("P")) {
    int c1 = cmd.indexOf(':');
    int c2 = cmd.indexOf(':', c1 + 1);
    int c3 = cmd.indexOf(':', c2 + 1);

    if (c2 == -1) { // Старый формат P1:50
      int n = cmd.substring(1, c1).toInt() - 1;
      float ml = cmd.substring(c1 + 1).toFloat();
      executePourByTime(n, ml, pumpRates[n], pumpInertia[n]);
    } else {
      int n = cmd.substring(1, c1).toInt() - 1;
      float ml = cmd.substring(c1 + 1, c2).toFloat();
      float rate = cmd.substring(c2 + 1, c3).toFloat();
      float inertia = cmd.substring(c3 + 1).toFloat();
      pumpRates[n] = rate;
      pumpInertia[n] = inertia;
      executePourByTime(n, ml, rate, inertia);
    }
  }

  // НАЛИВ ПО ВЕСАМ (3-е место): W3:50
  if (cmd.startsWith("W")) {
    int colon = cmd.indexOf(':');
    if (colon > 0) {
      int n = cmd.substring(1, colon).toInt() - 1; // должен быть 2 (т.е. 3-е место)
      float grams = cmd.substring(colon + 1).toFloat();
      if (n == 2) {
        executePourByWeight(n, grams);
      } else {
        client.println("ERR:WEIGHT_ONLY_PLACE_3");
      }
    }
    return;
  }

  // ПРОМЫВКА: RINSE:3:30:5.0 (Место 3, 30мл, скорость 5)
  if (cmd.startsWith("RINSE")) {
    int c1 = cmd.indexOf(':');
    int c2 = cmd.indexOf(':', c1 + 1);
    int c3 = cmd.indexOf(':', c2 + 1);

    if (c1 > 0 && c2 > 0) {
      int n = cmd.substring(c1 + 1, c2).toInt() - 1;
      float ml = cmd.substring(c2 + 1, c3).toFloat();
      float rate = cmd.substring(c3 + 1).toFloat();

      // Для промывки не учитываем инерцию (льем как есть)
      executePourByTime(n, ml, rate, 0); 
    }
    return;
  }
}

// ================= ИСПОЛНЕНИЕ НАЛИВА =================

void executePourByTime(int pumpIdx, float ml, float rate, float inertia) {
  if (pumpIdx < 0 || pumpIdx >= 5 || ml <= 0 || rate <= 0) return;
  if (!isGlassPresent(pumpIdx + 1)) {
    client.print("ERR:NO_GLASS:"); client.println(pumpIdx + 1);
    return;
  }

  client.print("START:"); client.println(pumpIdx + 1);
  stopRequested = false;

  float actualMl = ml - inertia;
  if (actualMl < 0) actualMl = 0;
  unsigned long runMs = (unsigned long)((actualMl / rate) * 1000.0);

  digitalWrite(pumpPins[pumpIdx], HIGH);

  unsigned long t0 = millis();
  while (millis() - t0 < runMs) {
    if (client && client.connected() && client.available()) {
      String check = client.readStringUntil('\n');
      check.trim();
      if (check == "STOP") { stopRequested = true; break; }
    }
    delay(10);
  }

  digitalWrite(pumpPins[pumpIdx], LOW);
  if (stopRequested) client.println("STOPPED");
  else { client.print("DONE:"); client.println(pumpIdx + 1); }
}

void executePourByWeight(int pumpIdx, float targetGrams) {
  if (pumpIdx != 2) return; // Только для 3-го места

  if (!isGlassPresent(pumpIdx + 1)) {
    client.print("ERR:NO_GLASS:"); client.println(pumpIdx + 1);
    return;
  }

  client.print("START:"); client.println(pumpIdx + 1);
  stopRequested = false;

  // 1. Запоминаем текущий вес (тару)
  float startWeight = scale.get_units(10);
  float targetWeight = startWeight + targetGrams;

  digitalWrite(pumpPins[pumpIdx], HIGH);

  unsigned long t0 = millis();
  unsigned long maxTime = 60000; // Защита: максимум 60 секунд

  while (millis() - t0 < maxTime) {
    if (client && client.connected() && client.available()) {
      String check = client.readStringUntil('\n');
      check.trim();
      if (check == "STOP") { stopRequested = true; break; }
    }

    float currentWeight = scale.get_units(3);
    // Отключаем насос за 3 грамма до цели (на инерцию струи)
    if (currentWeight >= targetWeight - 3.0) {
      break; 
    }
    delay(50);
  }

  digitalWrite(pumpPins[pumpIdx], LOW);
  if (stopRequested) client.println("STOPPED");
  else { 
    client.print("DONE:"); client.println(pumpIdx + 1); 
    Serial.print("Poured weight: "); Serial.println(scale.get_units(1));
  }
}
